const meta = $node["Parse & Prepare Data"].json;
const ai = $node["OpenAI: Generate Body"].json;

// Generate slug from topic
let slug = meta.topic.toLowerCase()
  .replace(/^what is /i, '')
  .replace(/^how to /i, '')
  .replace(/^understanding /i, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');

// Derive a human-readable, Title-Cased title from the (slug-style) topic.
// If the author already typed a spaced/capitalized title, keep it verbatim.
function slugToTitle(topic) {
  if (/[A-Z]/.test(topic)) return topic.trim();
  const small = new Set(['a','an','and','as','at','but','by','for','from','in','is','nor','of','on','or','per','the','to','via','vs','with']);
  const acronyms = { airpods:'AirPods', cbd:'CBD', cbt:'CBT', tmj:'TMJ', trt:'TRT', ent:'ENT', tv:'TV', diy:'DIY', adhd:'ADHD', ptsd:'PTSD' };
  const words = topic.split(/[-\s]+/).filter(Boolean);
  return words.map((w, i) => {
    if (acronyms[w]) return acronyms[w];
    if (i !== 0 && i !== words.length - 1 && small.has(w)) return w;
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(' ');
}
const title = slugToTitle(meta.topic);
// YAML-safe quoting: double-quote when the title contains an apostrophe.
const titleYaml = title.includes("'") ? '"' + title.replace(/"/g, '\\"') + '"' : "'" + title + "'";

// Format date as 'Month DD, YYYY' (e.g., 'July 13, 2023')
const dateObj = new Date();
const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const formattedDate = `${months[dateObj.getMonth()]} ${dateObj.getDate()}, ${dateObj.getFullYear()}`;
const order = meta.db.next_orders?.blog || 1;

// Extract metadata from AI response
let tags = [];
let description = '';
let categories = [];
let jsonFound = false;

try {
  const aiContent = ai.choices?.[0]?.message?.content || ai.content || '';
  console.log('AI Response length:', aiContent.length);

  // Look for JSON object in the response
  const jsonMatch = aiContent.match(/\{[\s\S]*?"tags"[\s\S]*?\}/g);
  if (jsonMatch && jsonMatch.length > 0) {
    console.log('Found JSON match:', jsonMatch[0].substring(0, 200));

    // Clean up the JSON string before parsing
    let jsonString = jsonMatch[0];

    // Fix common JSON issues
    jsonString = jsonString
      .replace(/,(\s*[}\]])/g, '$1') // Remove trailing commas
      .replace(/([^,{}\s])(\s*[}\]])/g, '$1$2') // Ensure proper comma placement
      .replace(/([^,{}\s])(\s*"[a-zA-Z_][a-zA-Z0-9_]*"\s*:)/g, '$1,$2'); // Add missing commas before properties

    try {
      const aiData = JSON.parse(jsonString);

      // Extract all metadata
      if (aiData.tags && Array.isArray(aiData.tags)) {
        tags = aiData.tags;
        console.log('Extracted tags:', tags.length);
      }

      if (aiData.description) {
        description = aiData.description;
        console.log('Extracted description:', description);
      }

      if (aiData.categories && Array.isArray(aiData.categories)) {
        categories = aiData.categories;
        console.log('Extracted categories:', categories);
      }

      jsonFound = true;
    } catch (jsonError) {
      console.log('JSON parsing failed, trying manual extraction:', jsonError.message);

      // Manual extraction as fallback
      const tagsMatch = aiContent.match(/"tags"\s*:\s*\[([^\]]+)\]/);
      const descMatch = aiContent.match(/"description"\s*:\s*"([^"]+)"/);
      const catsMatch = aiContent.match(/"categories"\s*:\s*\[([^\]]+)\]/);

      if (tagsMatch) {
        tags = tagsMatch[1].split(',').map(t => t.trim().replace(/["']/g, ''));
      }

      if (descMatch) {
        description = descMatch[1];
      }

      if (catsMatch) {
        categories = catsMatch[1].split(',').map(c => c.trim().replace(/["']/g, ''));
      }

      if (tags.length > 0 || description) {
        jsonFound = true;
        console.log('Manual extraction successful');
      }
    }
  }

  // Validate we got the required data
  if (!jsonFound || !description) {
    throw new Error('AI did not return required JSON with tags and description. Manual review needed.');
  }

  if (tags.length < 8) {
    console.log(`Warning: Only ${tags.length} tags found. Minimum 8 recommended.`);
  }

  if (categories.length === 0) {
    console.log('Warning: No categories found. Using default.');
    categories = ['Basics'];
  }

  // Validate categories against allowed list
  const allowedCategories = ['Basics', 'Management', 'Research', 'Psychology', 'Nutrition', 'Meditation', 'Sounds'];
  const invalidCategories = categories.filter(cat => !allowedCategories.includes(cat));
  if (invalidCategories.length > 0) {
    console.log(`Warning: Invalid categories found: ${invalidCategories.join(', ')}. Removing them.`);
    categories = categories.filter(cat => allowedCategories.includes(cat));
  }
  if (categories.length === 0) {
    console.log('No valid categories remaining. Using default.');
    categories = ['Basics'];
  }

} catch (e) {
  console.log('ERROR parsing AI response:', e.message);
  throw new Error(`Failed to extract data from AI response: ${e.message}. Please check AI output format.`);
}

description = description.replace(/\u2014/g, ' - ').replace(/[\u2013\u2011]/g, '-').replace(/  +/g, ' ');
// Safety net for over-long meta descriptions (target 120-135). Trim on a word boundary, no dangling punctuation.
if (description.length > 155) {
  description = description.slice(0, 152).replace(/\s+\S*$/, '').replace(/[\s,;:.-]+$/, '');
}
tags = (tags || []).slice(0, 3);

// Build frontmatter (matching tinnitus-blog format)
const frontmatterLines = [
  '---',
  `title: ${titleYaml}`,
  `date: '${formattedDate}'`,
  `description: '${description}'`,
  `image: '/images/${slug}.jpg'`,
  `tags: [${tags.map(t => `'${t}'`).join(', ')}]`
];

frontmatterLines.push('---');

const frontmatter = frontmatterLines.join('\n');

// Extract just the markdown body (remove any JSON at the end)
let body = ai.choices?.[0]?.message?.content || ai.content || '';
// Remove JSON object if it exists at the end
body = body.replace(/\s*```(?:json)?\s*\{[\s\S]*\}\s*```\s*$/i, '');
body = body.replace(/\s*\{[\s\S]*"(?:description|tags|social)"[\s\S]*\}\s*$/i, '').trim();

// Normalize AI punctuation: no em/en dashes or double hyphens; ensure ## on Highlighter headings
body = body.replace(/\u2014/g, ' - ').replace(/[\u2013\u2011]/g, '-').replace(/(^|[^-])--(?!-)/g, '$1-').replace(/  +/g, ' ');
body = body.replace(/^<Highlighter>/gm, '## <Highlighter>');

// Post must OPEN WITH A HEADING: <Blockquote> -> main <Image> -> first `## <Highlighter>`.
// If the AI left intro prose between the main image and the first heading, move that prose
// under the heading instead of shipping a headless opening paragraph.
const headless = body.match(/^([\s\S]*?<Image[^>]*\/>)\n+([\s\S]*?)\n+(## <Highlighter>[^\n]*)\n([\s\S]*)$/);
if (headless) {
  const intro = headless[2].trim();
  if (intro && !/^\s*(#{1,6}\s|<Image|<AdComponent|<Blockquote)/m.test(intro)) {
    body = `${headless[1]}\n\n${headless[3]}\n\n${intro}\n\n${headless[4].replace(/^\n+/, '')}`;
    console.log('Moved headless intro under the first heading');
  }
}

// Ads must never sit directly next to an image: relocate offending ads before the conclusion heading
let movedAds = 0;
body = body.replace(/(<Image[^>]*\/>)\s*\n+\s*<AdComponent \/>/g, (m, img) => { movedAds++; return img; });
body = body.replace(/<AdComponent \/>\s*\n+\s*(<Image[^>]*\/>)/g, (m, img) => { movedAds++; return img; });
if (movedAds > 0) {
  const concl = body.match(/^## <Highlighter>Conclusion[^\n]*$/m);
  if (concl) body = body.replace(concl[0], '<AdComponent />\n\n' + concl[0]);
}

// Dedupe internal links: keep first occurrence, unlink repeats (keep bold text)
const seenLinks = new Set();
body = body.replace(/(\*\*)?\[([^\]]+)\]\((\/[^)]+)\)(\*\*)?/g, (m, b1, text, url, b2) => {
  if (seenLinks.has(url)) return (b1 || '') + text + (b2 || '');
  seenLinks.add(url);
  return m;
});

// Strip "phantom bold links": bolded phrases that name a page linked elsewhere in the
// article but carry no link of their own, so they render as bold text that looks like a
// broken link. Guidelines cap each page at one link, so the fix is to un-bold, not relink.
const linkedTitles = new Set();
const normPhrase = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const linkScan = /\[[^\]]*\]\((\/[^)]*)\)/g;
let linkMatch;
while ((linkMatch = linkScan.exec(body)) !== null) {
  const seg = linkMatch[1].split(/[?#]/)[0].replace(/\/+$/, '').split('/').pop() || '';
  const slugTitle = normPhrase(seg);
  if (slugTitle) linkedTitles.add(slugTitle);
}
// Scan links and bold spans in one pass, so anything belonging to a real link is consumed
// by the link branch and left alone.
let unbolded = 0;
body = body.replace(/\[[^\]]*\]\([^)]*\)|\*\*([^*\n]+)\*\*/g, (full, inner) => {
  if (inner === undefined || /[\[\]()]/.test(inner)) return full;
  if (!linkedTitles.has(normPhrase(inner))) return full;
  unbolded++;
  return inner;
});
if (unbolded > 0) console.log(`Un-bolded ${unbolded} phantom bold link(s)`);

// Force the first body image to match the main article image
body = body.replace(/<Image\s+src="\/images\/[^"]*"/, `<Image src="/images/${slug}.jpg"`);

return [{
  json: {
    mdx: `${frontmatter}\n\n${body}`,
    slug,
    topic: meta.topic,
    title,
    formattedDate,
    order,
    db: meta.db,
    tags,
    description,
    categories
  }
}];

const data = $json;
const filePath = `${data.slug}.mdx`;
const commitMessage = `New post: ${data.topic}`;

return [{
  json: {
    ...data,
    filePath,
    commitMessage
  }
}];

// Validate file write was successful
const fileResult = $input.first().json;
if (!fileResult || fileResult.error) {
  throw new Error(`File write failed: ${fileResult?.error || 'Unknown error'}`);
}

// Get post data from Build Frontmatter + MDX node
const postData = $node["Build Frontmatter + MDX"].json;
if (!postData || !postData.topic || !postData.slug) {
  throw new Error('Post data not found or incomplete');
}

// Get and validate database data
const dbData = postData.db;
if (!dbData) {
  throw new Error('Database data not found');
}

// Create updated database with proper structure
const updatedDb = {
  ...dbData,
  blog: { ...(dbData.blog || {}) },
  next_orders: { ...(dbData.next_orders || { blog: 1 }) }
};

// Use slug as key (matching existing structure)
const postKey = postData.slug;

// Check if post already exists
if (updatedDb.blog[postKey]) {
  throw new Error(`Post '${postData.topic}' already exists in database`);
}

// Add new post to database
updatedDb.blog[postKey] = {
  slug: postData.slug,
    title: postData.title || postData.topic
};

// Increment next order counter
updatedDb.next_orders.blog = (updatedDb.next_orders.blog || 0) + 1;

// Return success with updated database
return [{ 
  json: { 
    db: updatedDb, 
    fileSuccess: true, 
    dbSuccess: true,
    postAdded: postKey,
    topic: postData.topic
  } 
}];
